import { readFile, writeFile } from "node:fs/promises";
import { basename } from "node:path";

export async function convertFile(input, to, output) {
  const base = process.env.CONVRT_API_URL;
  const key = process.env.CONVRT_API_KEY;
  if (!base || !key) throw new Error("Set API URL and key");
  const origin = new URL(base);
  if (origin.protocol !== "https:" &&
      !(origin.protocol === "http:" && ["localhost", "127.0.0.1", "[::1]"].includes(origin.hostname)))
    throw new Error("Use HTTPS outside loopback");
  const signal = AbortSignal.timeout(180000);
  const headers = { Authorization: `Bearer ${key}` };
  async function request(path, init = {}) {
    const response = await fetch(new URL(path, origin), {
      ...init, headers, signal, redirect: "error",
    });
    if (!response.ok) throw new Error(`API HTTP ${response.status}`);
    return response;
  }
  const body = new FormData();
  body.set("file", new File([await readFile(input)], basename(input)));
  body.set("to", to);
  let job = await (await request("/v1/jobs", { method: "POST", body })).json();
  try {
    while (["queued", "running"].includes(job.status)) {
      await new Promise(resolve => setTimeout(resolve, 1000));
      job = await (await request(`/v1/jobs/${job.id}`)).json();
    }
    if (job.status !== "succeeded") throw new Error(job.error ?? "Conversion failed");
    const result = await request(`/v1/jobs/${job.id}/download`);
    await writeFile(output, new Uint8Array(await result.arrayBuffer()), { flag: "wx" });
  } finally {
    const cleanup = await fetch(new URL(`/v1/jobs/${job.id}`, origin), {
      method: "DELETE", headers, redirect: "error", signal: AbortSignal.timeout(10000),
    }).catch(() => undefined);
    if (!cleanup || ![204, 404].includes(cleanup.status))
      console.error("Cleanup deferred; server retention still applies.");
  }
}
